    """Complete repeated horizontal and vertical marker lines with color 2."""
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(value for row in grid for value in row).most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    out = [row[:] for row in grid]
    if not points:
        return out

    r0 = min(r for r, _ in points)
    r1 = max(r for r, _ in points)
    c0 = min(c for _, c in points)
    c1 = max(c for _, c in points)

    # Complete vertical runs that contain at least two original markers.
    for c in range(c0, c1 + 1):
        marked_rows = [r for r in range(r0, r1 + 1) if grid[r][c] != bg]
        if len(marked_rows) >= 2:
            for r in range(marked_rows[0], marked_rows[-1] + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2

    # The outermost rows form the top/bottom edges; other rows are completed
    # when they contain at least three original markers.
    for r in range(r0, r1 + 1):
        marked_cols = [c for c in range(c0, c1 + 1) if grid[r][c] != bg]
        if r in (r0, r1) or len(marked_cols) >= 3:
            if marked_cols:
                for c in range(marked_cols[0], marked_cols[-1] + 1):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out
